package dev.cheeseowl.gmbg;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicInteger;

/** Closed vocabulary and synthetic trace tests, not execution of Android suggestion items. */
public class SuggestionDiagnosticsTest {
    @Test public void normalQueryBranchIsOnlyACandidate(){assertEquals(SuggestionKinds.Flow.TEMPLATE_BRANCH_CANDIDATE,SuggestionKinds.flow(true,false,false));assertFalse(QueryScope.allows("sug_page","",false));assertFalse(QueryScope.allows("webview","",false));}
    @Test public void nativeAndJavascriptSuggestionSourcesStayDistinct(){assertEquals(SuggestionKinds.Source.SUG_PAGE,SuggestionKinds.source("sug_page"));assertEquals(SuggestionKinds.Source.WEBVIEW,SuggestionKinds.source("webview"));assertEquals(SuggestionKinds.Source.LOCAL_SUG_WORD,SuggestionKinds.source("local_sug_word"));assertEquals(SuggestionKinds.Source.QUANSOU_SUGWORD,SuggestionKinds.source("quansou_sugword"));}
    @Test public void directAndAiBranchPrecedenceMatchesX(){assertEquals(SuggestionKinds.Flow.DIRECT_URL_BRANCH,SuggestionKinds.flow(false,true,true));assertEquals(SuggestionKinds.Flow.DIRECT_URL_BRANCH,SuggestionKinds.flow(true,true,false));assertEquals(SuggestionKinds.Flow.AI_BRANCH,SuggestionKinds.flow(true,false,true));assertEquals(SuggestionKinds.Flow.EMPTY,SuggestionKinds.flow(false,false,true));}
    @Test public void ordinaryTextUnicodeAndSpecialCharactersAreNotUrls(){for(String q:new String[]{"fixed text","中文 % & # 🦉","100%","a&b","a#b"})assertEquals(SuggestionKinds.Input.TEXT,SuggestionKinds.input(q));}
    @Test public void directWebAndNonWebAreClassifiedWithoutDecoding(){assertEquals(SuggestionKinds.Input.HTTPS,SuggestionKinds.input("https://www.baidu.com/s?wd=fixed%26word"));assertEquals(SuggestionKinds.Input.HTTP,SuggestionKinds.input("http://example.test/"));for(String u:new String[]{"intent://private","tel:123","content://private","market://details","file:///private","mi://settings"})assertEquals(SuggestionKinds.Input.OTHER_SCHEME,SuggestionKinds.input(u));assertEquals(SuggestionKinds.Input.MALFORMED,SuggestionKinds.input("https://%bad space"));}
    @Test public void arbitraryPrivateSourcesOnlyProduceClosedOther(){assertEquals(SuggestionKinds.Source.OTHER,SuggestionKinds.source("private-person-query-123"));assertEquals(SuggestionKinds.Source.NONE,SuggestionKinds.source(null));}
    @Test public void malformedAiMetadataCannotBeClaimedOrdinary(){assertEquals(Privacy.Tri.TRUE,SuggestionKinds.aiMetadata("1",true));assertEquals(Privacy.Tri.FALSE,SuggestionKinds.aiMetadata("0",true));assertEquals(Privacy.Tri.FALSE,SuggestionKinds.aiMetadata(null,false));assertEquals(Privacy.Tri.UNKNOWN,SuggestionKinds.aiMetadata(1,true));assertEquals(Privacy.Tri.UNKNOWN,SuggestionKinds.aiMetadata(new Object(),true));}
    @Test public void webTabLocalTabAndDefaultAreDistinctHints(){assertEquals(SuggestionKinds.Tab.WEB_ALL,SuggestionKinds.tab("web_all",true));assertEquals(SuggestionKinds.Tab.LOCAL_ALL,SuggestionKinds.tab("local_all",true));assertEquals(SuggestionKinds.Tab.DEFAULT_WEB_ALL,SuggestionKinds.tab(null,false));assertEquals(SuggestionKinds.Tab.OTHER,SuggestionKinds.tab("private-tab",true));}
    @Test public void hostClassesAreExactAndNeverUseContains(){assertEquals(SuggestionKinds.Host.BAIDU,SuggestionKinds.host("www.baidu.com"));assertEquals(SuggestionKinds.Host.BING,SuggestionKinds.host("CN.BING.COM"));assertEquals(SuggestionKinds.Host.GOOGLE,SuggestionKinds.host("www.google.com"));for(String h:new String[]{"google.com.private.test","private-baidu.com","www.bing.com.evil"})assertEquals(SuggestionKinds.Host.OTHER,SuggestionKinds.host(h));}
    @Test public void specialPathsAndUnknownPathsAreNotOrdinaryProof(){assertEquals(SuggestionKinds.Path.SEARCH_PATH,SuggestionKinds.path("/s"));assertEquals(SuggestionKinds.Path.AI_PATH,SuggestionKinds.path("/aiSearch/"));assertEquals(SuggestionKinds.Path.ONESEARCH_PATH,SuggestionKinds.path("/oneSearch/"));assertEquals(SuggestionKinds.Path.OTHER,SuggestionKinds.path("/private/contact"));}
    @Test public void localCompletionKindsDoNotTurnIntoWebSearch(){assertEquals(SuggestionKinds.Completion.LOCAL_APP,SuggestionKinds.completion("local_app"));assertEquals(SuggestionKinds.Completion.LOCAL_SETTINGS,SuggestionKinds.completion("local_settings"));assertEquals(SuggestionKinds.Completion.OTHER,SuggestionKinds.completion("contact_person"));for(String source:new String[]{"local_app","contact_person","local_settings","local_sug_word","sug_page","webview","ad","hotword_whole_net"})assertFalse(QueryScope.allows(source,"",false));}
    @Test public void bottomButtonAndOriginalBrowserPolicyRemainIndependent(){assertTrue(QueryScope.allows("right_search_btn","",false));assertTrue(QueryScope.allows("keyboard_search_btn","",false));assertTrue(WebPolicy.allows("android.intent.action.VIEW","https://www.baidu.com/s?wd=fixed","https://www.baidu.com/s?wd=fixed","baidu",false,false,null,false));assertFalse(WebPolicy.allows("android.intent.action.VIEW","https://example.test/","https://example.test/","baidu",true,false,null,false));}
    @Test public void completionToQueryToBrowserHasOneLinkedTrace(){Trace t=new Trace();Trace.Frame n=t.enter(Trace.Kind.COMPLETION),g=t.enter(Trace.Kind.UI_SEARCH),x=t.enter(Trace.Kind.UI_EXECUTE),q=t.enter(Trace.Kind.QUERY),k=t.enter(Trace.Kind.WEB_PREPARE),c=t.enter(Trace.Kind.BROWSER);assertEquals(n.id(),g.parent());assertEquals(g.id(),x.parent());assertEquals(x.id(),q.parent());assertEquals(q.id(),k.parent());assertEquals(k.id(),c.parent());assertEquals(Trace.Source.OTHER,t.source());for(Trace.Frame f:new Trace.Frame[]{c,k,q,x,g,n})t.exit(f);assertEquals(0,t.enter(Trace.Kind.QUERY).parent());}
    @Test public void directLinkTraceHasNoInventedQueryNode(){Trace t=new Trace();Trace.Frame n=t.enter(Trace.Kind.WEB_DIRECT),k=t.enter(Trace.Kind.WEB_PREPARE),c=t.enter(Trace.Kind.BROWSER);assertEquals(n.id(),k.parent());assertEquals(k.id(),c.parent());t.exit(c);t.exit(k);t.exit(n);assertEquals(0,t.enter(Trace.Kind.WEB_DIRECT).parent());}
    @Test public void serviceBranchIsNotLabeledAsBrowser(){Trace t=new Trace();Trace.Frame completion=t.enter(Trace.Kind.COMPLETION),service=t.enter(Trace.Kind.BUSINESS_DISPATCH);assertEquals(completion.id(),service.parent());assertEquals(Trace.Kind.BUSINESS_DISPATCH,service.kind());assertEquals(Trace.Source.OTHER,t.source());}
    @Test public void asynchronousWorkCannotInheritUiTrace() throws Exception {Trace t=new Trace();t.enter(Trace.Kind.SUGGEST_JS);AtomicLong parent=new AtomicLong(-1);Thread thread=new Thread(()->parent.set(t.enter(Trace.Kind.QUERY).parent()));thread.start();thread.join();assertEquals(0,parent.get());}
    @Test public void brokenObserverCannotChangeOriginalResultOrCallCount() throws Throwable {AtomicInteger calls=new AtomicInteger();Object expected=new Object();Object actual=Around.run(()->{throw new RuntimeException("fixture");},()->{calls.incrementAndGet();return expected;},(r,b)->{throw new RuntimeException("fixture");},()->{});assertSame(expected,actual);assertEquals(1,calls.get());}
    @Test public void originalFailureIsPreservedAndTraceCleaned(){Trace t=new Trace();Trace.Frame[] frame={null};Error expected=new Error("fixture");try{Around.run(()->frame[0]=t.enter(Trace.Kind.SUGGEST_NATIVE),()->{throw expected;},(r,b)->{},()->t.exit(frame[0]));fail();}catch(Throwable actual){assertSame(expected,actual);}assertEquals(0,t.enter(Trace.Kind.QUERY).parent());}
    @Test public void rawInputsCannotEscapeLogBoundary(){StringBuilder sink=new StringBuilder();DiagnosticLog log=new DiagnosticLog(sink::append);log.emit(DiagnosticLog.Event.SUGGEST_PATH,DiagnosticLog.Hook.SUGGEST_JS,DiagnosticLog.Phase.BEFORE,null,"private query","https://private.test/?q=x",new Object(),SuggestionKinds.Source.WEBVIEW);assertFalse(sink.toString().contains("private"));assertTrue(sink.toString().contains("WEBVIEW"));}
}
